sp_angular_provider.script:
[function () {
  'use strict';

  // The editor theme cycles auto -> light -> dark -> auto on a single button (not a 3-way direct
  // pick) - matches the sidenav's own theme toggle interaction.
  var EDITOR_THEME_ORDER = ['auto', 'light', 'dark'];
  var EDITOR_THEME_LABELS = { auto: 'Auto', light: 'Light', dark: 'Dark' };

  var THEME_KEY, EDITOR_THEME_KEY; // set by init()
  var appTheme, editorTheme;

  function systemPrefersDark() {
    return !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
  }
  function load(key) {
    try { return localStorage.getItem(key); } catch (e) { return null; }
  }
  function save(key, value) {
    try { localStorage.setItem(key, value); } catch (e) {}
  }
  function applyApp() { document.documentElement.setAttribute('data-theme', appTheme); }
  // "auto" isn't a real CSS value; resolve it to whichever concrete theme (light/dark) matches the
  // app theme right now, so the output panes track the app toggle. The resolved value (never "auto")
  // is what the template binds to the DOM.
  function resolveEditor() { return editorTheme === 'auto' ? appTheme : editorTheme; }

  var svc = {
    // Call once per app before use, with the app's own localStorage key prefix, so each app keeps
    // its own independent stored theme. A manual choice (stored) always wins; with no stored choice
    // yet, default to the OS/browser's prefers-color-scheme so the app matches the system out of the box.
    init: function (keyPrefix) {
      THEME_KEY = keyPrefix + 'Theme';
      EDITOR_THEME_KEY = keyPrefix + 'EditorTheme';
      appTheme = load(THEME_KEY) || (systemPrefersDark() ? 'dark' : 'light');
      editorTheme = load(EDITOR_THEME_KEY) || 'auto';
      applyApp();
      return svc;
    },
    // A snapshot the controller mirrors onto vm after each mutation. Toggling the app theme also
    // moves editorApplied when the editor is on "auto", so callers re-read the whole state.
    readState: function () {
      return { theme: appTheme, editorTheme: editorTheme, editorApplied: resolveEditor() };
    },
    editorLabel: function () { return EDITOR_THEME_LABELS[editorTheme]; },
    toggleApp: function () {
      appTheme = appTheme === 'dark' ? 'light' : 'dark';
      save(THEME_KEY, appTheme);
      applyApp();
    },
    cycleEditor: function () {
      editorTheme = EDITOR_THEME_ORDER[(EDITOR_THEME_ORDER.indexOf(editorTheme) + 1) % EDITOR_THEME_ORDER.length];
      save(EDITOR_THEME_KEY, editorTheme);
    },
  };
  return svc;
}]

[function () {
  'use strict';

  var svc = {
    confirm: { open: false, title: '', body: '', cancel: '', ok: '' },
  };
  var callback = null;

  svc.open = function (opts, onOk) {
    opts = opts || {};
    svc.confirm.title = opts.title || 'Are you sure?';
    svc.confirm.body = opts.body || '';
    svc.confirm.cancel = opts.cancel || 'Cancel';
    svc.confirm.ok = opts.ok || 'Confirm';
    callback = onOk;
    svc.confirm.open = true;
  };
  svc.close = function () {
    svc.confirm.open = false;
    callback = null;
  };
  svc.accept = function () {
    var cb = callback;
    svc.close();
    if (cb) { cb(); }
  };

  return svc;
}]

['$sce', function ($sce) {
  'use strict';

  function slugify(title) {
    return String(title || '').toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-');
  }
  // Plain-text search corpus for a section: title + tag-stripped body, lowercased once here rather
  // than per keystroke. Built at model time and cached on the section.
  function stripHtml(html) {
    var div = document.createElement('div');
    div.innerHTML = html || '';
    return (div.textContent || div.innerText || '');
  }

  // Trust each html fragment ONCE into a stable structure - ng-bind-html re-evaluates per digest, so
  // a fresh trustAsHtml() per render would never settle. Returns a view model the directive binds to.
  function build(rawDoc) {
    rawDoc = rawDoc || {};
    return {
      lead: rawDoc.lead ? $sce.trustAsHtml(rawDoc.lead) : null,
      parts: (rawDoc.parts || []).map(function (part) {
        return {
          // 'chapter-' prefix keeps chapter ids in a namespace disjoint from section ids, so a
          // chapter and a section that slugify the same never collide as scroll targets.
          id: part.id || ('chapter-' + slugify(part.title)),
          title: part.title,
          group: part.group || null,
          lead: part.lead ? $sce.trustAsHtml(part.lead) : null,
          sections: (part.sections || []).map(function (s) {
            var body = s.html || '';
            return {
              id: s.id || slugify(s.title),
              title: s.title,
              html: $sce.trustAsHtml(body),
              searchText: (String(s.title || '') + ' ' + stripHtml(body)).toLowerCase(),
            };
          }),
        };
      }),
    };
  }

  // True when the section should show for the current query (empty query shows everything).
  function matches(section, query) {
    query = (query || '').trim().toLowerCase();
    if (!query) { return true; }
    return section.searchText.indexOf(query) !== -1;
  }

  return { build: build, matches: matches, slugify: slugify };
}]

['$timeout', function ($timeout) {
  return {
    restrict: 'A',
    link: function (scope, element, attrs) {
      var root = element[0];
      var lastFocus = document.activeElement;

      $timeout(function () {
        var target = attrs.coreModalFocus ? document.getElementById(attrs.coreModalFocus) : null;
        if (!target) { target = root.querySelector('button, textarea'); }
        if (target && target.focus) { target.focus(); }
      });

      // Only button/textarea count as tab-stops here, matching this app's other interactive
      // controls (gs-select, condition rows) which aren't plain form fields.
      function focusable() {
        return Array.prototype.slice.call(root.querySelectorAll('button, textarea'))
          .filter(function (el) { return !el.disabled && el.offsetParent !== null; });
      }
      function onKeydown(e) {
        if (e.key === 'Escape') {
          scope.$apply(function () { scope.$eval(attrs.coreModal); });
          return;
        }
        if (e.key !== 'Tab') { return; }
        var list = focusable();
        if (!list.length) { return; }
        var first = list[0], last = list[list.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
      document.addEventListener('keydown', onKeydown);

      scope.$on('$destroy', function () {
        document.removeEventListener('keydown', onKeydown);
        if (lastFocus && lastFocus.focus) { lastFocus.focus(); }
      });
    }
  };
}]

function () {
  return {
    restrict: 'A',
    link: function (scope, el, attrs) {
      var name = scope.$eval(attrs.coreSyncAttr);
      function apply(val) {
        if (val === null || val === undefined) { el.removeAttr(name); }
        else { el.attr(name, val); }
      }
      apply(scope.$eval(attrs.coreSyncValue));
      scope.$watch(attrs.coreSyncValue, apply);
    }
  };
}

['DocViewerService', '$timeout', function (DocViewerService, $timeout) {
  return {
    restrict: 'E',
    scope: { rawDoc: '=doc' },
    template:
      '<div class="doc">' +
        '<div class="doc-lead" ng-if="model.lead" ng-bind-html="model.lead"></div>' +
        '<div class="doc-layout">' +
          '<aside class="doc-rail">' +
            '<input class="doc-search" type="text" ng-model="query" placeholder="Search the docs…" aria-label="Search the docs">' +
            '<nav class="doc-nav" aria-label="On this page">' +
              '<div class="doc-nav-part" ng-repeat="part in model.parts" ng-if="partVisible(part)">' +
                '<a class="doc-nav-chapter" href="" ng-click="scrollTo(part.id); $event.preventDefault()">{{part.title}}</a>' +
                '<a class="doc-nav-link" ng-repeat="s in part.sections" ng-if="match(s)" href="" ' +
                   'ng-class="{active: activeId === s.id}" ng-click="scrollTo(s.id); $event.preventDefault()">{{s.title}}</a>' +
              '</div>' +
            '</nav>' +
          '</aside>' +
          '<div class="doc-content">' +
            '<section class="doc-part" ng-repeat="part in model.parts" ng-if="partVisible(part)">' +
              '<h2 class="doc-chapter" id="{{part.id}}">{{part.title}}</h2>' +
              '<div class="doc-chapter-lead" ng-if="part.lead" ng-bind-html="part.lead"></div>' +
              '<article class="doc-section" ng-repeat="s in part.sections" ng-if="match(s)" id="{{s.id}}">' +
                '<h3 class="doc-section-title">{{s.title}}</h3>' +
                '<div class="doc-section-body" ng-bind-html="s.html"></div>' +
              '</article>' +
            '</section>' +
            '<p class="doc-empty" ng-if="!anyVisible()">No sections match “{{query}}”.</p>' +
          '</div>' +
        '</div>' +
      '</div>',
    link: function (scope, element) {
      var root = element[0];

      function rebuild() { scope.model = DocViewerService.build(scope.rawDoc); }
      rebuild();
      scope.$watch('rawDoc', function (nv, ov) { if (nv !== ov) { rebuild(); reobserve(); } });

      scope.query = '';
      scope.activeId = null;
      scope.match = function (s) { return DocViewerService.matches(s, scope.query); };
      scope.partVisible = function (p) { return p.sections.some(scope.match); };
      scope.anyVisible = function () { return scope.model.parts.some(scope.partVisible); };

      /* Hand-rolled eased window scroll rather than el.scrollIntoView({behavior:'smooth'}) - native
         smooth scroll silently no-ops here (instant works, smooth doesn't; the same behavior
         Standards documented and worked around). Driving window.scrollTo per frame is the mechanism
         that reliably works. Respects prefers-reduced-motion. */
      function animateWindowScroll(targetY) {
        var start = window.pageYOffset || window.scrollY;
        var delta = targetY - start;
        var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (Math.abs(delta) < 2 || reduced) { window.scrollTo(0, targetY); return; }
        var duration = Math.min(450, Math.max(200, Math.abs(delta) * 0.15)), t0 = null;
        function frame(ts) {
          if (t0 === null) { t0 = ts; }
          var p = Math.min((ts - t0) / duration, 1);
          var eased = 1 - Math.pow(1 - p, 3); // ease-out cubic
          window.scrollTo(0, start + delta * eased);
          if (p < 1) { requestAnimationFrame(frame); }
        }
        requestAnimationFrame(frame);
      }
      // Attribute selector (not #id) because ids come from arbitrary titles - a numeric-leading or
      // punctuation-bearing slug would break a CSS #id selector but is fine as [id="..."].
      scope.scrollTo = function (id) {
        var el = root.querySelector('[id="' + (window.CSS && CSS.escape ? CSS.escape(id) : id) + '"]');
        if (!el) { return; }
        var y = (window.pageYOffset || window.scrollY) + el.getBoundingClientRect().top - 12;
        animateWindowScroll(Math.max(0, y));
      };

      /* Scroll-spy: highlight whichever section heading sits nearest the top of the viewport. The
         -70% bottom rootMargin shrinks the "active" band to the top slice of the viewport so a
         section only wins once scrolled up there; recompute the topmost from the full known state
         each callback (IntersectionObserver only reports elements whose state flipped). */
      var tops = {};
      var lastId = null;
      // Near the bottom of the page the last sections can't reach the top band (the page bottoms out
      // first), so without this the final nav links would never highlight - the observer keeps an
      // earlier section lit. At the bottom, force the last section active instead.
      function atBottom() {
        var d = document.documentElement;
        return d.scrollHeight > window.innerHeight + 4 &&
          (window.pageYOffset || 0) + window.innerHeight >= d.scrollHeight - 4;
      }
      function commit(id) { scope.$applyAsync(function () { scope.activeId = id; }); }
      function recompute() {
        if (atBottom() && lastId) { commit(lastId); return; }
        var visible = Object.keys(tops)
          .filter(function (id) { return tops[id] !== null; })
          .map(function (id) { return { id: id, top: tops[id] }; })
          .sort(function (a, b) { return a.top - b.top; });
        if (visible.length) { commit(visible[0].id); }
      }
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) { tops[e.target.id] = e.isIntersecting ? e.boundingClientRect.top : null; });
        recompute();
      }, { rootMargin: '0px 0px -70% 0px', threshold: 0 });

      function reobserve() {
        observer.disconnect();
        tops = {};
        $timeout(function () {
          var secs = root.querySelectorAll('.doc-section');
          lastId = secs.length ? secs[secs.length - 1].id : null;
          Array.prototype.forEach.call(secs, function (s) { observer.observe(s); });
        });
      }
      reobserve();
      // Re-observe when search filtering adds/removes sections from the DOM.
      scope.$watch('query', function (nv, ov) { if (nv !== ov) { reobserve(); } });

      // The observer only fires on intersection flips; the final scroll pixels may not cause one, so
      // a scroll listener asserts the bottom section directly.
      var onScroll = function () { if (atBottom() && lastId) { commit(lastId); } };
      window.addEventListener('scroll', onScroll, { passive: true });

      scope.$on('$destroy', function () { observer.disconnect(); window.removeEventListener('scroll', onScroll); });
    },
  };
}]

[function () {
  'use strict';

  return {
    DOC: {
      lead: '<p><strong>Core</strong> is the shared foundation for the ServiceNow AngularJS app suite. It hosts reusable providers — services and directives — that every other app injects <em>by name</em>, plus this generic documentation viewer. Deployed once, reused everywhere.</p>',
      parts: [
        {
          title: 'Getting Started',
          group: 'Guide',
          lead: '<p>How an app depends on Core and reuses what it provides.</p>',
          sections: [
            {
              id: 'depend-on-core',
              title: 'Depend on Core',
              html: '<p>Declare Core as a module dependency, then inject its providers by name — no copying, no vendoring:</p>' +
                    '<pre class="doc-code"><code>angular.module(\'glideStudio\', [\'core\']);</code></pre>' +
                    '<p>At runtime every app on a Service Portal page shares one Angular injector, so a widget resolves Core\'s providers by name as long as the Core app is installed on the instance.</p>',
            },
            {
              id: 'build-a-doc-widget',
              title: 'Build a doc widget',
              html: '<p>Feed <code>&lt;core-doc&gt;</code> a doc-data object and it renders a searchable, navigable document — the same viewer you are reading now:</p>' +
                    '<pre class="doc-code"><code>&lt;core-doc doc="vm.doc"&gt;&lt;/core-doc&gt;</code></pre>' +
                    '<p>The content is plain data (chapters and sections of HTML); the search box, the “on this page” rail, and the scroll-spy highlight all come for free.</p>',
            },
          ],
        },
        {
          title: 'Shared Providers',
          group: 'Reference',
          lead: '<p>The reusable services and directives Core currently hosts.</p>',
          sections: [
            {
              id: 'themeservice',
              title: 'ThemeService',
              html: '<p>The app-wide light/dark toggle (sets <code>data-theme</code> on the document). Each app calls <code>ThemeService.init(\'&lt;appKey&gt;\')</code> once so its stored preference stays independent from every other app.</p>',
            },
            {
              id: 'confirmmodalservice',
              title: 'ConfirmModalService',
              html: '<p>A generic confirmation dialog — title, body, Cancel / OK, and a callback run on OK. Any destructive action reuses it via <code>open(opts, onOk)</code>.</p>',
            },
            {
              id: 'coremodal',
              title: 'coreModal',
              html: '<p>An attribute directive that adds shared modal chrome to any overlay: Escape to close, focus trapping, focus restore on close. Add the attribute; no shared code to edit per modal.</p>',
            },
            {
              id: 'coresyncattr',
              title: 'coreSyncAttr',
              html: '<p>An attribute directive that sets a DOM attribute synchronously during link — closing the one-frame gap that interpolated <code>ng-attr-*</code> leaves on freshly-inserted elements.</p>',
            },
          ],
        },
      ],
    },
  };
}]

sp_widget.client_script:
api.controller = function (CoreDocsService) {
  'use strict';
  var vm = this;
  vm.doc = CoreDocsService.DOC;
};

sp_widget.css:
/* Shared design tokens for the ServiceNow app suite - the single source of truth for the suite's
   SCSS color/spacing/type vocabulary. Every value is declared with `!default`, which is what makes
   a widget portable across portals and instances:

   - The packager inlines these declarations at the TOP of each widget's own <css> field (before the
     widget's scoped rules). See tools/packager + an app's build-deploy.js `sharedScssPartials`.
   - `!default` means "use this value UNLESS the variable is already defined." A ServiceNow portal
     theme's own CSS Variables are compiled AHEAD of a widget's SCSS, so if the target portal already
     defines a token (e.g. `$brand-primary`), that wins and this default is a no-op. Where the portal
     defines nothing, the widget falls back to these bundled defaults and still looks right.

   So an app references these token names in its scss/app.scss (it does NOT redefine them), and gets
   both a consistent suite vocabulary AND portability for free. Category-variant naming
   (`$background-*`, `$text-*`, `$brand-*`, `$border-*`, ...) per the suite convention.

   NOTE: these are the COMPILE-TIME ($) layer - portal/brand integration. An app's own runtime
   light/dark flipping is a SEPARATE concern (CSS custom properties + `data-theme`), seeded from
   these values but living in the app's own scss. */// ---------- Surfaces ----------
$background-primary:   #f4f5f7 !default;// page background (most used)
$background-secondary: #ffffff !default;// panel / card surface
$background-tertiary:  #fbfbfd !default;// subtle alternate surface// ---------- Text ----------
$text-primary: #1c2128 !default;// body text
$text-muted:   #6b7280 !default;// secondary text
$text-faint:   #9aa1ab !default;// tertiary / placeholder// ---------- Brand / accent ----------
$brand-primary:       #054b80 !default;
$brand-primary-hover: #043a63 !default;
$brand-primary-soft:  #e6eef5 !default;// tinted accent background
$brand-secondary:     #6d3fc9 !default;// ---------- Borders ----------
$border-primary: #e2e5ea !default;
$border-strong:  #d2d6dd !default;// ---------- Status ----------
$status-danger:  #dc2626 !default;
$status-success: #15803d !default;
$status-warning: #f0ad4e !default;// ---------- Radius ----------
$border-radius-base:  10px !default;
$border-radius-small: 7px  !default;// ---------- Shadow ----------
$box-shadow-base: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.10) !default;// ---------- Spacing ----------
$spacing-xs: 4px  !default;
$spacing-sm: 8px  !default;
$spacing-md: 12px !default;
$spacing-lg: 16px !default;
$spacing-xl: 24px !default;// ---------- Typography ----------
$font-family-base: 'Montserrat', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !default;
$font-family-mono: 'SF Mono', 'JetBrains Mono', Menlo, Consolas, monospace !default;/* Core - styling source for Core's own widget: the generic documentation/wiki viewer (the
   <core-doc> directive rendering CoreDocsService's content).

   SCSS SOURCE, not hand-edited CSS - css/app.css is a BUILD OUTPUT (npm run build:css). Edit this
   file, not that one.

   Selectors are written PLAIN (`:root`, `body`, `.doc-*`, ...) so they apply directly in this
   standalone dev harness; the packager's scopeScss() re-scopes them under the widget wrapper class
   (`.core-widget`) at deploy time - do NOT hand-wrap them here. Color tokens are real SCSS variables
   with `!default` so the deploy build ships them into the widget's own <css> field as fallbacks: a
   host portal theme that already defines the token wins; otherwise this default applies. Phase 5
   replaces this local token block with the shared theme-foundation partial, inlined by the packager. */// ---------- Light (default) palette ----------// Compile-time tokens ($background-*, $text-*, $brand-*, ...) come from the shared foundation// (tools/theme-foundation/_tokens.scss), inlined at build: the dev build prepends it via// `build:css` (cat partial | sass --stdin); the packager prepends it into the widget's own <css>// via `sharedScssPartials` (see scripts/build-deploy.js). This app does NOT redefine them - so it// shares the suite vocabulary and inherits a host portal's theme tokens where present.// Runtime custom properties (the app's own light/dark layer, seeded from the shared SCSS tokens)..core-widget {
  --core-bg: #{$background-primary};
  --core-panel: #{$background-secondary};
  --core-panel-alt: #{$background-tertiary};
  --core-border: #{$border-primary};
  --core-text: #{$text-primary};
  --core-muted: #{$text-muted};
  --core-faint: #{$text-faint};
  --core-accent: #{$brand-primary};
  --core-accent-soft: #{$brand-primary-soft};
  --core-code-bg: #{$background-tertiary};
}.core-widget[data-theme='dark'] {
  --core-bg: #10131a;
  --core-panel: #1a1f29;
  --core-panel-alt: #20262f;
  --core-border: #2a3040;
  --core-text: #e7ebf2;
  --core-muted: #9aa3b6;
  --core-faint: #6b7385;
  --core-accent: #5b9fe0;
  --core-accent-soft: rgba(91, 159, 224, 0.16);
  --core-code-bg: #0f1319;
}.core-widget * { box-sizing: border-box; }.core-widget, .core-widget { height: 100%; margin: 0; }.core-widget {
  font-family: $font-family-base;
  background: var(--core-bg);
  color: var(--core-text);
  line-height: 1.6;
}@media (prefers-reduced-motion: reduce) {.core-widget * { scroll-behavior: auto !important; } }.core-widget .app { max-width: 1040px; margin: 0 auto; padding: 24px 24px 80px; }/* header */.core-widget .core-head { display: flex; align-items: center; gap: 12px; padding: 4px 0 20px; margin-bottom: 24px;
  border-bottom: 1px solid var(--core-border); }.core-widget .core-badge { font-weight: 700; font-size: 13px; letter-spacing: .02em; color: #fff; background: var(--core-accent);
  padding: 4px 11px; border-radius: 7px; }.core-widget .core-head-title { color: var(--core-muted); font-size: 14px; }/* doc viewer */.core-widget .doc-lead { font-size: 16px; color: var(--core-muted); max-width: 70ch; margin: 0 0 28px; }.core-widget .doc-lead :first-child { margin-top: 0; }.core-widget .doc-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 40px; align-items: start; }.core-widget .doc-rail { position: sticky; top: 16px; align-self: start; }.core-widget .doc-search { width: 100%; font: inherit; font-size: 13px; color: var(--core-text); background: var(--core-panel);
  border: 1px solid var(--core-border); border-radius: 8px; padding: 8px 11px; margin-bottom: 16px; }.core-widget .doc-search::placeholder { color: var(--core-faint); }.core-widget .doc-search:focus { outline: none; border-color: var(--core-accent); box-shadow: 0 0 0 3px var(--core-accent-soft); }.core-widget .doc-nav { display: flex; flex-direction: column; font-size: 13px; }.core-widget .doc-nav-part { margin-bottom: 14px; }.core-widget .doc-nav-chapter { display: block; font-weight: 600; color: var(--core-text); text-decoration: none; padding: 3px 0; }.core-widget .doc-nav-chapter:hover { color: var(--core-accent); }.core-widget .doc-nav-link { display: block; color: var(--core-muted); text-decoration: none; padding: 4px 0 4px 12px;
  border-left: 2px solid transparent; margin-left: 1px; transition: color .12s, border-color .12s; }.core-widget .doc-nav-link:hover { color: var(--core-accent); }.core-widget .doc-nav-link.active { color: var(--core-accent); border-left-color: var(--core-accent); font-weight: 600; }.core-widget .doc-content { min-width: 0; }.core-widget .doc-part { margin-bottom: 40px; }.core-widget .doc-chapter { font-size: 22px; font-weight: 700; margin: 0 0 8px; scroll-margin-top: 16px;
  padding-bottom: 8px; border-bottom: 1px solid var(--core-border); }.core-widget .doc-chapter-lead { color: var(--core-muted); margin: 0 0 20px; }.core-widget .doc-chapter-lead :first-child { margin-top: 0; }.core-widget .doc-section { margin: 24px 0; scroll-margin-top: 16px; }.core-widget .doc-section-title { font-size: 16px; font-weight: 650; margin: 0 0 6px; }.core-widget .doc-section-body :first-child { margin-top: 0; }.core-widget .doc-section-body p { margin: 8px 0; }.core-widget .doc-section-body code { font-family: $font-family-mono; font-size: .86em; background: var(--core-code-bg);
  border: 1px solid var(--core-border); border-radius: 4px; padding: .05em .36em; }.core-widget .doc-code { background: var(--core-code-bg); border: 1px solid var(--core-border); border-radius: 8px;
  padding: 12px 14px; overflow-x: auto; margin: 12px 0; }.core-widget .doc-code code { font-family: $font-family-mono; font-size: 12.5px; background: none; border: 0; padding: 0; color: var(--core-text); }.core-widget .doc-empty { color: var(--core-muted); font-size: 14px; }@media (max-width: 720px) {.core-widget .doc-layout { grid-template-columns: 1fr; gap: 20px; }.core-widget .doc-rail { position: static; }
}

